import{CRITERIA,STAGES,DEFAULT_WEIGHTS,score,todayMadrid,status,rank,budget,csv,validateBackup}from './model.mjs';
const $=id=>document.getElementById(id),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),key='top-manta-ajuts-v1';
let data,state={version:1,weights:[...DEFAULT_WEIGHTS],work:{}},compared=['creixess','enfortim','ka210'],active;
const money=n=>new Intl.NumberFormat('ca-ES',{style:'currency',currency:'EUR',maximumFractionDigits:0}).format(n);
function dateLabel(d){if(!d)return 'Data pendent de confirmar';if(/^\d{4}-\d{2}-\d{2}$/.test(d))return new Date(d+'T12:00:00Z').toLocaleDateString('ca-ES',{timeZone:'Europe/Madrid'});return new Date(d).toLocaleString('ca-ES',{dateStyle:'short',timeStyle:'short',timeZone:'Europe/Madrid'});}
function badge(r){const s=status(r),c=s==='Oberta'?'open':s==='Tancada'?'closed':'watch';return '<span class="tag '+c+'">'+esc(s)+'</span>';}
function toast(s){$('toast').textContent=s;$('toast').style.display='block';clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('toast').style.display='none',4500);}
function save(){try{localStorage.setItem(key,JSON.stringify(state));$('save-status').textContent='Seguiment desat en aquest navegador · sense sincronització entre dispositius.';}catch{$('save-status').textContent='No s’ha pogut desar al navegador. Exporta una còpia del seguiment.';}}
function renderWeights(){$('weights').innerHTML=CRITERIA.map((c,i)=>'<div class="weight"><label for="weight-'+i+'">'+c[1]+'<output id="value-'+i+'">'+state.weights[i]+'</output></label><input id="weight-'+i+'" data-weight="'+i+'" type="range" min="0" max="100" value="'+state.weights[i]+'"></div>').join('');}
function renderDecision(){const ranked=rank(data.rows,state.weights,state.work),best=ranked[0];
$('recommendation').innerHTML=best?'<div class="recommendation"><span class="score">'+best.score+'<span class="small"> /100</span></span><div class="eyebrow">MILLOR ENCAIX PER PREPARAR</div><h3>'+esc(best.name)+'</h3>'+badge(best)+'<p>'+esc(best.fit)+'</p><button class="text-button" data-detail="'+best.id+'">Revisa la idoneïtat i els requisits ↗</button></div>':'<div class="recommendation"><h3>Cal un pes superior a zero.</h3><p>Ajusta almenys un criteri per calcular prioritats.</p></div>';
$('compare-count').textContent=compared.length+'/3 seleccionades';
$('comparison').innerHTML=compared.map(id=>{const r=data.rows.find(r=>r.id===id);return '<article class="compare-card"><div><span class="small muted">'+esc(r.area)+'</span><h4>'+esc(r.name)+'</h4></div><div class="scoreline"><strong>'+ (score(r,state.weights)??'—')+'</strong><span class="small"> /100</span></div><div>'+badge(r)+'</div><p>'+esc(r.amount)+'</p><p><b>Qui:</b> '+esc(r.entity)+'</p><p><b>Accés:</b> '+esc(r.gate)+'</p><button class="text-button" data-detail="'+r.id+'">Veure fitxa ↗</button></article>';}).join('')+Array.from({length:3-compared.length},()=>'<div class="empty">Marca una opció a la taula per comparar-la.</div>').join('');}
function filtered(){const q=$('search').value.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();return data.rows.filter(r=>(!q||[r.name,r.entity,r.proposal,r.project].join(' ').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().includes(q))&&(!$('area').value||r.area===$('area').value)&&(!$('kind').value||r.kind===$('kind').value)&&(!$('project').value||r.project===$('project').value)&&(!$('official-status').value||status(r)===$('official-status').value)&&(!$('stage').value||(state.work[r.id]?.stage??'Pendent')===$('stage').value)&&(!$('only-open').checked||status(r)==='Oberta')).sort((a,b)=>(score(b,state.weights)??-1)-(score(a,state.weights)??-1)||a.name.localeCompare(b.name,'ca'));}
function renderTable(){const list=filtered();$('count').textContent=list.length+' de '+data.rows.length+' línies · ordre per prioritat orientativa';$('rows').innerHTML=list.length?list.map(r=>'<tr><td><input type="checkbox" data-compare="'+r.id+'" aria-label="Compara '+esc(r.name)+'" '+(compared.includes(r.id)?'checked':'')+'></td><td><button class="row-title" data-detail="'+r.id+'">'+esc(r.name)+'</button><div class="row-meta">'+esc(r.area)+' · '+esc(r.project)+'</div><div class="row-meta">'+esc(r.entity)+'</div></td><td>'+esc(r.proposal)+'</td><td>'+badge(r)+'<div class="row-meta">'+esc(dateLabel(r.deadline))+'</div></td><td>'+esc(r.amount)+'<div class="row-meta">'+esc(r.kind)+'</div></td><td><span class="points">'+(score(r,state.weights)??'—')+'</span><div class="row-meta">/100 · '+esc(r.gate)+'</div></td><td><span class="tag">'+esc(state.work[r.id]?.stage??'Pendent')+'</span><div class="row-meta">'+(state.work[r.id]?.validated?'Requisits revisats per tu':'Elegibilitat pendent')+'</div>'+(state.work[r.id]?.due?'<div class="row-meta">Interna: '+esc(dateLabel(state.work[r.id].due))+'</div>':'')+'</td><td><button class="button" data-detail="'+r.id+'">Fitxa ↗</button></td></tr>').join(''):'<tr><td colspan="8">Cap resultat amb aquests filtres.</td></tr>';}
function renderUrgent(){const open=data.rows.filter(r=>status(r)==='Oberta');$('open').textContent=open.length;$('urgent').innerHTML=open.length?open.map(r=>'<article><div class="eyebrow">'+(r.id==='creixess'?'REVISIÓ URGENT':'OBERTA · ENCAIX CONDICIONAT')+'</div><h3>'+esc(r.name)+'</h3><p><b>Fins a '+esc(dateLabel(r.deadline))+' · hora de Barcelona</b></p><p>'+esc(r.id==='creixess'?'Validar avui la capacitat de presentar un projecte empresarial ja definit.':r.risk)+'</p><button data-detail="'+r.id+'">Comprova què presentar i com ↗</button></article>').join(''):'<article><h3>Cap termini obert verificat al radar.</h3><p>Consulta les fonts per detectar noves finestres; aquesta pàgina no s’actualitza automàticament.</p></article>';}
function render(){renderDecision();renderTable();}
function detail(id){active=id;const r=data.rows.find(r=>r.id===id),w=state.work[id]??{stage:'Pendent',owner:'',due:'',validated:false,notes:''};$('detail-title').textContent=r.name;
const section=(name,text)=>'<div class="detail-section"><h3>'+name+'</h3><p>'+esc(text)+'</p></div>';
$('detail-body').innerHTML='<div>'+badge(r)+' <span class="tag">'+esc(r.area)+'</span> <span class="tag">'+esc(r.kind)+'</span></div><div class="detail-grid">'+section('Entitat i accés',r.entity+' · '+r.gate)+section('Termini oficial',dateLabel(r.deadline)+(r.deadline?' · Europe/Madrid':''))+section('Import publicat',r.amount)+section('Condicions econòmiques',r.funding)+'</div>'+section('Què presentaria Top Manta · proposta editorial',r.proposal)+section('Idoneïtat i rellevància · valoració editorial',r.fit)+section('Condicions, riscos i exclusions',r.risk)+section('Com i quan preparar-ho · proposta de treball',r.steps)+section('Documentació a reunir',r.docs)+section('Què s’ha verificat',r.evidence)+'<div class="detail-section"><h3>Fonts oficials · revisió '+esc(r.checked)+'</h3><p><a href="'+esc(r.source)+'" target="_blank" rel="noopener">Obre la font principal ↗</a>'+(r.source2?' · <a href="'+esc(r.source2)+'" target="_blank" rel="noopener">Segona font ↗</a>':'')+'</p><p class="small muted">Revalida bases i modificacions abans de presentar. Els requisits de Top Manta no estan acreditats en aquest radar.</p></div>';
$('work-stage').value=w.stage;$('owner').value=w.owner;$('due').value=w.due;$('validated').checked=w.validated;$('notes').value=w.notes;if(!$('detail').open)$('detail').showModal();}
function download(content,type,name){const url=URL.createObjectURL(new Blob([content],{type})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1500);}
function calc(){const values=['budget','rate','cap','advance','hours','hourly'].map(id=>Number($(id).value));if(values.some((v,i)=>!Number.isFinite(v)||v<0||v>([100000000,100,100000000,100,100000,100000][i]))){$('budget-output').textContent='Introdueix valors vàlids dins dels límits indicats.';return;}const b=budget(...values);$('budget-output').innerHTML='<div class="budget-results">'+[['Ajut màxim simulat',b.grant],['Aportació pròpia mínima',b.own],['Tresoreria inicial estimada',b.initial],['Cost intern de gestió',b.admin]].map(([s,v])=>'<div><strong>'+money(v)+'</strong><span>'+s+'</span></div>').join('')+'</div>';}
async function init(){try{data=await fetch('data.json').then(r=>{if(!r.ok)throw Error();return r.json();});try{const stored=localStorage.getItem(key);if(stored)state=validateBackup(JSON.parse(stored),data.rows.map(r=>r.id));}catch{$('save-status').textContent='No s’ha pogut recuperar el seguiment desat. Es mostra la base original.';}
$('total').textContent=data.rows.length;$('freshness').textContent='Revisió documental: 19/10/2026 · Consulta: '+todayMadrid()+' · '+data.scope+' La pàgina no consulta novetats automàticament.';
for(const [id,field]of [['area','area'],['kind','kind'],['project','project']])$(id).insertAdjacentHTML('beforeend',[...new Set(data.rows.map(r=>r[field]))].sort().map(s=>'<option>'+esc(s)+'</option>').join(''));
$('official-status').insertAdjacentHTML('beforeend',[...new Set(data.rows.map(r=>status(r)))].sort().map(s=>'<option>'+esc(s)+'</option>').join(''));
$('stage').insertAdjacentHTML('beforeend',STAGES.map(s=>'<option>'+s+'</option>').join(''));$('work-stage').innerHTML=STAGES.map(s=>'<option>'+s+'</option>').join('');
renderWeights();renderUrgent();render();calc();
for(const id of ['search','area','kind','project','stage','official-status','only-open'])$(id).addEventListener('input',renderTable);
$('weights').addEventListener('input',e=>{const i=Number(e.target.dataset.weight);if(!Number.isInteger(i))return;state.weights[i]=Number(e.target.value);$('value-'+i).textContent=state.weights[i];save();render();});
document.querySelectorAll('[data-preset]').forEach(b=>b.addEventListener('click',()=>{state.weights={balanced:[40,25,20,15],impact:[45,40,10,5],capacity:[20,15,35,30]}[b.dataset.preset];renderWeights();save();render();}));
$('reset').onclick=()=>{state.weights=[...DEFAULT_WEIGHTS];renderWeights();save();render();};
document.addEventListener('click',e=>{const b=e.target.closest('[data-detail]');if(b)detail(b.dataset.detail);});
$('rows').addEventListener('change',e=>{if(!e.target.dataset.compare)return;const id=e.target.dataset.compare;if(e.target.checked){if(compared.length===3){e.target.checked=false;toast('Pots comparar un màxim de tres opcions. Desmarca’n una primer.');return;}compared.push(id);}else compared=compared.filter(v=>v!==id);renderDecision();});
$('close').onclick=()=>$('detail').close();
$('work-form').onsubmit=e=>{e.preventDefault();state.work[active]={stage:$('work-stage').value,owner:$('owner').value,due:$('due').value,validated:$('validated').checked,notes:$('notes').value};save();render();$('detail').close();toast('Seguiment actualitzat.');};
$('export-csv').onclick=()=>download(csv(data.rows,state.weights,state.work),'text/csv;charset=utf-8','top-manta-radar-ajuts.csv');
$('export-json').onclick=()=>download(JSON.stringify(state,null,2),'application/json','top-manta-seguiment-ajuts.json');
$('import-json').onclick=()=>$('import-file').click();$('import-file').onchange=async e=>{const f=e.target.files[0];if(!f)return;try{if(f.size>1000000)throw Error('El fitxer supera 1 MB.');const candidate=validateBackup(JSON.parse(await f.text()),data.rows.map(r=>r.id));if(confirm('Vols substituir el seguiment i els pesos d’aquest navegador amb aquesta còpia?')){state=candidate;save();renderWeights();render();toast('Còpia importada.');}}catch(err){toast(err.message||'No s’ha pogut importar.');}e.target.value='';};
for(const id of ['budget','rate','cap','advance','hours','hourly'])$(id).addEventListener('input',calc);
}catch{$('freshness').textContent='No s’han pogut carregar les fitxes. Recarrega la pàgina; les dades de seguiment no s’han modificat.';}}
init();
